import BaseService from "./BaseService.js";
import { toLine } from "@tmagic/utils";
import { cloneDeep } from "lodash-es";
// packages/editor/src/sdk/services/Events.ts
var canUsePluginMethods = {
	async: [],
	sync: [
		"setEvent",
		"getEvent",
		"setMethod",
		"getMethod"
	]
};
var Events = class extends BaseService {
	eventMap;
	methodMap;
	constructor(ctx) {
		super([...canUsePluginMethods.async.map((methodName) => ({
			name: methodName,
			isAsync: true
		})), ...canUsePluginMethods.sync.map((methodName) => ({
			name: methodName,
			isAsync: false
		}))]);
		this.eventMap = ctx.reactivity.reactive({});
		this.methodMap = ctx.reactivity.reactive({});
	}
	setEvents(events) {
		Object.keys(events).forEach((type) => {
			this.setEvent(toLine(type), events[type] || []);
		});
	}
	setEvent(type, events) {
		this.eventMap[toLine(type)] = [...events];
	}
	getEvent(type, _data = {}) {
		return cloneDeep(this.eventMap[toLine(type)]) || [];
	}
	setMethods(methods) {
		Object.keys(methods).forEach((type) => {
			this.setMethod(toLine(type), methods[type] || []);
		});
	}
	setMethod(type, method) {
		this.methodMap[toLine(type)] = [...method];
	}
	getMethod(type, _data = {}) {
		return cloneDeep(this.methodMap[toLine(type)]) || [];
	}
	resetState() {
		Object.keys(this.eventMap).forEach((type) => delete this.eventMap[type]);
		Object.keys(this.methodMap).forEach((type) => delete this.methodMap[type]);
	}
	destroy() {
		this.resetState();
		this.removeAllListeners();
		this.removeAllPlugins();
	}
	usePlugin(options) {
		super.usePlugin(options);
	}
};
export { Events as default };
