import { CONTAINER_HIGHLIGHT_CLASS_NAME, ContainerHighlightType, RenderType } from "@tmagic/stage";
import { getIdFromEl } from "@tmagic/utils";
// packages/editor/src/editorProps.ts
/**
* 「属性配置表单校验」联动能力的 provide/inject 注入键。
* 使用 Symbol 避免与其它字符串键冲突，供 PropsPanel / FormPanel 注入判断校验失败时是否仍更新节点并记录错误。
*
* 注入值是 ComputedRef：Editor 用 `computed(() => props.enablePropsFormValidate ?? false)` 提供，
* 保证外部动态切换该 prop 时子孙组件能同步拿到最新值；子孙侧用 `.value` 读取。
*/
var ENABLE_PROPS_FORM_VALIDATE = Symbol("enablePropsFormValidate");
var defaultEditorProps = {
	renderType: RenderType.IFRAME,
	disabledMultiSelect: false,
	alwaysMultiSelect: false,
	disabledPageFragment: false,
	disabledFlashTip: false,
	disabledStageOverlay: false,
	containerHighlightClassName: CONTAINER_HIGHLIGHT_CLASS_NAME,
	containerHighlightDuration: 800,
	containerHighlightType: ContainerHighlightType.DEFAULT,
	containerHighlightAddOnly: false,
	disabledShowSrc: false,
	disabledDataSource: false,
	disabledCodeBlock: false,
	componentGroupList: () => [],
	datasourceList: () => [],
	historyListExtraTabs: () => [],
	menu: () => ({
		left: [],
		right: []
	}),
	layerContentMenu: () => [],
	stageContentMenu: () => [],
	propsConfigs: () => ({}),
	propsValues: () => ({}),
	eventMethodList: () => ({}),
	datasourceValues: () => ({}),
	datasourceConfigs: () => ({}),
	canSelect: (el) => Boolean(getIdFromEl()(el) && !el.dataset.tmagicPageFragmentContainerId),
	isContainer: (el) => el.classList.contains("magic-ui-container"),
	codeOptions: () => ({}),
	customContentMenu: (menus) => menus
};
export { ENABLE_PROPS_FORM_VALIDATE, defaultEditorProps };
