import BaseService from "../sdk/services/BaseService.js";
import { Protocol } from "../sdk/services/WebStorage.js";
import { editorService, storageService } from "./sdk-instance.js";
import "../utils/const.js";
import { convertToNumber } from "@tmagic/utils";
import { shallowReactive } from "vue";
// packages/editor/src/services/ui.ts
var state = shallowReactive({
	uiSelectMode: false,
	showSrc: false,
	showStylePanel: true,
	zoom: 1,
	stageContainerRect: {
		width: 0,
		height: 0
	},
	stageRect: {
		width: 375,
		height: 817
	},
	columnWidth: {
		left: 0,
		center: 0,
		right: 0
	},
	minLeftColumnWidth: 345,
	minCenterColumnWidth: 400,
	minRightColumnWidth: 300,
	showGuides: true,
	hasGuides: false,
	showRule: true,
	propsPanelSize: "small",
	showAddPageButton: true,
	showPageListButton: true,
	hideSlideBar: false,
	sideBarItems: [],
	sideBarActiveTabName: "",
	navMenuRect: {
		left: 0,
		top: 0,
		width: 0,
		height: 0
	},
	frameworkRect: {
		width: 0,
		height: 0,
		left: 0,
		top: 0
	}
});
state.columnWidth.left = Math.max(storageService.getItem("$MagicEditorLeftColumnWidthData", { protocol: Protocol.NUMBER }) || 345, state.minLeftColumnWidth);
state.columnWidth.right = Math.max(storageService.getItem("$MagicEditorRightColumnWidthData", { protocol: Protocol.NUMBER }) || 480, state.minRightColumnWidth);
var canUsePluginMethods = {
	async: ["zoom", "calcZoom"],
	sync: []
};
var Ui = class extends BaseService {
	constructor() {
		super(canUsePluginMethods.async.map((methodName) => ({
			name: methodName,
			isAsync: true
		})));
	}
	set(name, value) {
		const mask = editorService.get("stage")?.mask;
		if (name === "stageRect") {
			this.setStageRect(value);
			return;
		}
		if (name === "showGuides") mask?.showGuides(value);
		if (name === "showRule") mask?.showRule(value);
		const preValue = state[name];
		state[name] = value;
		if (preValue !== value) this.emit("state-change", name, value, preValue);
	}
	get(name) {
		return state[name];
	}
	async zoom(zoom) {
		this.set("zoom", (this.get("zoom") * 100 + zoom * 100) / 100);
		if (this.get("zoom") < .1) this.set("zoom", .1);
	}
	async calcZoom() {
		const { stageRect, stageContainerRect } = state;
		const { height, width } = stageContainerRect;
		if (!width || !height) return 1;
		let stageWidth = convertToNumber(stageRect.width, width);
		let stageHeight = convertToNumber(stageRect.height, height);
		stageWidth = stageWidth + 30;
		stageHeight = stageHeight + 30;
		if (width > stageWidth && height > stageHeight) return 1;
		return Math.min((width - 60) / stageWidth || 1, (height - 80) / stageHeight || 1);
	}
	resetState() {
		this.set("showSrc", false);
		this.set("uiSelectMode", false);
		this.set("zoom", 1);
		this.set("stageContainerRect", {
			width: 0,
			height: 0
		});
	}
	destroy() {
		this.resetState();
		this.removeAllListeners();
		this.removeAllPlugins();
	}
	usePlugin(options) {
		super.usePlugin(options);
	}
	async setStageRect(value) {
		state.stageRect = {
			...state.stageRect,
			...value
		};
		state.zoom = await this.calcZoom();
	}
};
var ui_default = new Ui();
export { ui_default as default };
